INSERT OR REPLACE INTO monster_species (code,name,rarity,element,personality,body_type,appearance,skill_name,skill_description,growth_rate,base_power,image_prompt,image_path) VALUES
('xgs_fluffy_01','棉耳团团','N','火','黏人','长尾灵巧','棉耳团团是一只毛绒系的兔狐代表怪兽，主色为陶棕、古铜、苔藓绿，身体材质呈现星尘质感。它拥有古铜镜片眼，五官比例圆润可爱但带有N级卡牌气场；体型为长尾灵巧，姿态是蜷卧在装饰巢穴里。身上保留唯一图鉴编号 xgs_fluffy_01 的尾饰，尾饰与火元素纹章相连，周围漂浮绒线花环、软云、蒲公英种子。性格黏人，外观必须与其他小怪兽明显不同，颜色、材质、五官、道具、尾饰和背景符号都独立。','火绒守护','火绒守护会释放火元素的兔狐形光效，先在脚下展开专属纹章，再把聊天积累的心情能量转化为守护、增幅或控制效果。技能发动时绒线花环、软云、蒲公英种子会被点亮，融合后可继承部分能量并强化纹章亮度。',1.006,104,'领养小怪兽 OpenClaw 收藏卡牌，竖版 3:4 完整卡牌构图。画面风格：将穆夏风格的华丽装饰背景与天野喜孝风格的飘逸线条、梦幻人物/动物气质进行融合，杰作，极繁主义，扁平插画，线绘插画，工笔素描风格，色彩艳丽，梦幻感，高级审美，高品质细节，超高清分辨率，最佳品质。顶部文字清晰中大，任务标题醒目，清晰显示稀有度 N；底部预留名字铭牌区域，中文名字“棉耳团团”要清晰。卡面边框：木质边框，柔和自然光，适合基础陪伴感。主体根据不同任务/元素刻画不同动物代表任务属性：兔狐代表火属性与毛绒系任务气质。详细角色设定：棉耳团团是一只毛绒系的兔狐代表怪兽，主色为陶棕、古铜、苔藓绿，身体材质呈现星尘质感。它拥有古铜镜片眼，五官比例圆润可爱但带有N级卡牌气场；体型为长尾灵巧，姿态是蜷卧在装饰巢穴里。身上保留唯一图鉴编号 xgs_fluffy_01 的尾饰，尾饰与火元素纹章相连，周围漂浮绒线花环、软云、蒲公英种子。性格黏人，外观必须与其他小怪兽明显不同，颜色、材质、五官、道具、尾饰和背景符号都独立。 技能视觉：火绒守护会释放火元素的兔狐形光效，先在脚下展开专属纹章，再把聊天积累的心情能量转化为守护、增幅或控制效果。技能发动时绒线花环、软云、蒲公英种子会被点亮，融合后可继承部分能量并强化纹章亮度。背景包含绒线花环、软云、蒲公英种子，但中心怪兽轮廓必须清楚；可爱、收藏卡、游戏卡牌、高级装饰，不要照片写实，不要恐怖，不要杂乱乱码，不要遮挡标题和铭牌。唯一图鉴编号：xgs_fluffy_01。','images/N/xgs_fluffy_01.png'),
